using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps;using MapSharedProps.EditorTools;using MapTunnels.EditorTools;using MapTunnels;
public static class Cave202Checks{
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence202");const string Old="Assets/MapSharedPropsGenerated/Pilot 17";
 [Serializable]class LoadRow{public int count,visible,meshes,materials,textures;public long meshBytes;public double cpuMedianMs;}
 [Serializable]class Report{public bool pass;public int formalPrefabs,placed,triangles,materials,textures,colliders;public bool prefabSceneReload;public string folder;public LoadRow[] loads;public string[] limits;}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.08f,.09f,.10f);RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;Shader.SetGlobalVector("_TDPineWind",Vector4.zero);}
 static void Shot(Camera c,string name){var t=Shared117Review.Image(c,1280,720);File.WriteAllBytes(Path.Combine(Out,name+".png"),t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}
 static Camera Camera(){var c=new GameObject("offscreen").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.03f,.035f,.04f);c.fieldOfView=45;c.nearClipPlane=.03f;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;return c;}
 static string Snap(GameObject root){return string.Join("\n",root.GetComponentsInChildren<MeshFilter>().OrderBy(x=>x.name).Select(x=>x.name+"|"+ColliderSnapshot109.MeshHash(x.sharedMesh)+"|"+JsonUtility.ToJson(new Data{n=x.sharedMesh.normals,uv=x.sharedMesh.uv,c=x.sharedMesh.colors})+"|"+x.GetComponent<Renderer>().sharedMaterial.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS")));}
 [Serializable]class Data{public Vector3[] n;public Vector2[] uv;public Color[] c;}
 public static void Run(){Directory.CreateDirectory(Out);try{Empty();var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
  var result=MapSharedPropsBuilder.Build(Path.Combine(Root,"Input197-before"));Check(result.prefabs.Count==20&&result.placed==20&&result.skipped==0,"formal20");int tri=0;
  foreach(var kv in result.prefabs){var prev=AssetDatabase.LoadAssetAtPath<GameObject>(Old+"/"+kv.Key+".prefab");var oldMesh=prev.GetComponent<MeshFilter>().sharedMesh;var newMesh=kv.Value.GetComponent<MeshFilter>().sharedMesh;Check(ColliderSnapshot109.MeshHash(oldMesh)==ColliderSnapshot109.MeshHash(newMesh)&&oldMesh.normals.SequenceEqual(newMesh.normals)&&oldMesh.uv.SequenceEqual(newMesh.uv)&&oldMesh.colors.SequenceEqual(newMesh.colors),"mesh unchanged "+kv.Key);Check(prev.GetComponentsInChildren<Collider>().Length==0&&kv.Value.GetComponentsInChildren<Collider>().Length==0,"existing visual-only contract");tri+=newMesh.triangles.Length/3;
   var a=prev.GetComponent<Renderer>().sharedMaterial;var b=kv.Value.GetComponent<Renderer>().sharedMaterial;Check(!a.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS")&&b.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS"),"before fails/after opt-in "+kv.Key);Check(a.shader==b.shader&&a.renderQueue==b.renderQueue,"shader queue unchanged");foreach(string prop in a.GetTexturePropertyNames())Check(a.GetTexture(prop)==b.GetTexture(prop),"texture refs unchanged");foreach(string prop in new[]{"_BaseColor","_PineBand","_PineWaves","_PinePhase","_PineResponse","_PlantTouch"})Check(a.GetVector(prop)==b.GetVector(prop),"material vector preserved");foreach(string prop in new[]{"_Cutoff","_Cull","_PlantCombinedLimit"})Check(a.GetFloat(prop)==b.GetFloat(prop),"material float preserved");Check(a.shaderKeywords.OrderBy(x=>x).SequenceEqual(b.shaderKeywords.Where(x=>x!="SMALL_PROP_LOCAL_LIGHTS").OrderBy(x=>x)),"only intended keyword");Check(!ShaderUtil.ShaderHasError(b.shader),"compile");}
  Check(tri==1123,"no geometry increase");string snapshot=Snap(result.root),folder=result.assetDirectory;var rootPrefab=PrefabUtility.SaveAsPrefabAsset(result.root,folder+"/cave202-group.prefab");AssetDatabase.SaveAssets();UnityEngine.Object.DestroyImmediate(result.root);var restored=(GameObject)PrefabUtility.InstantiatePrefab(rootPrefab);Check(Snap(restored)==snapshot,"prefab state persists");string scene=folder+"/cave202.unity";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),scene);string rootName=restored.name;Empty();EditorSceneManager.OpenScene(scene);restored=UnityEngine.Object.FindObjectsByType<GameObject>(FindObjectsSortMode.None).Single(x=>x.name==rootName);Check(Snap(restored)==snapshot,"scene persists");var mats=restored.GetComponentsInChildren<Renderer>().Select(x=>x.sharedMaterial).Distinct().ToArray();var tex=mats.SelectMany(x=>x.GetTexturePropertyNames().Select(x.GetTexture)).Where(x=>x).Distinct().ToArray();Check(mats.Length==20&&tex.Length==1,"existing pack sharing");
  Field(result.prefabs);var loads=Load(result.prefabs["cnd020"]);
  File.WriteAllText(Path.Combine(Out,"checks.json"),JsonUtility.ToJson(new Report{pass=true,formalPrefabs=20,placed=20,triangles=tri,materials=20,textures=1,colliders=0,prefabSceneReload=true,folder=folder,loads=loads,limits=new[]{"Exact cave-decoration20 route only; old small-prop55 preserved by separate201 checks and static code branch exclusion","Native cave pack is existing visual-only route: zero Collider, not newly removed","Forward/Forward+ point/spot/SH/main/off/shadow diagnostic202; vertex-light mode untested","CPU Camera.Render short samples only; GPU/mobile/Player not tested","No new Web assets/export schema; existing Web output unchanged"}},true));AssetDatabase.SaveAssets();EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Field(Dictionary<string,GameObject> prefabs){Empty();var tunnel=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"Cave202");Check(tunnel.built,"existing mine");var cam=Camera();var hero=new GameObject("view anchor").transform;hero.position=new Vector3(12,0,10.5f);var cut=tunnel.root.GetComponent<MapTunnelCutaway>();cut.hero=hero;cut.viewCamera=cam;var ids=new[]{"cnd020","cnd001","cnd014"};
  foreach(string stage in new[]{"before","after"}){var objs=new List<GameObject>();foreach(string id in ids){var prefab=stage=="before"?AssetDatabase.LoadAssetAtPath<GameObject>(Old+"/"+id+".prefab"):prefabs[id];var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);o.transform.position=new Vector3(id=="cnd020"?12:id=="cnd001"?11.1f:12.9f,0,id=="cnd020"?10.5f:9.6f);o.transform.rotation=Quaternion.Euler(0,id=="cnd020"?90:0,0);objs.Add(o);}foreach(string view in new[]{"normal","close","back"}){var target=hero.position+Vector3.up*.3f;cam.transform.position=view=="normal"?hero.position+new Vector3(0,9,-6.3f):target+(view=="back"?new Vector3(-.2f,1.4f,3.2f):new Vector3(.2f,1.4f,-3.2f));cam.transform.LookAt(target);typeof(MapTunnelCutaway).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cut,null);Shot(cam,"mine-"+view+"-"+stage);}foreach(var o in objs)UnityEngine.Object.DestroyImmediate(o);}
 }
 static LoadRow[] Load(GameObject prefab){Empty();var cam=Camera();var light=new GameObject("local").AddComponent<Light>();light.type=LightType.Point;light.range=10;light.intensity=4;light.transform.position=new Vector3(0,3,0);var rows=new List<LoadRow>();foreach(int n in new[]{9,225}){int side=(int)Mathf.Sqrt(n);var objs=new List<GameObject>();for(int i=0;i<n;i++){var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);o.transform.position=new Vector3((i%side-side/2)*2.2f,0,(i/side-side/2)*2.2f);objs.Add(o);}cam.transform.position=new Vector3(side*1.3f,side*1.8f,-side*1.8f);cam.transform.LookAt(Vector3.zero);var rt=new RenderTexture(640,360,24);rt.Create();cam.targetTexture=rt;for(int i=0;i<3;i++)cam.Render();var times=new List<double>();for(int i=0;i<7;i++){var sw=System.Diagnostics.Stopwatch.StartNew();cam.Render();sw.Stop();times.Add(sw.Elapsed.TotalMilliseconds);}times.Sort();var renderers=objs.Select(x=>x.GetComponent<Renderer>()).ToArray();var meshes=objs.Select(x=>x.GetComponent<MeshFilter>().sharedMesh).Distinct().ToArray();var mats=renderers.Select(x=>x.sharedMaterial).Distinct().ToArray();var textures=mats.SelectMany(x=>x.GetTexturePropertyNames().Select(x.GetTexture)).Where(x=>x).Distinct().ToArray();var planes=GeometryUtility.CalculateFrustumPlanes(cam);Check(meshes.Length==1&&mats.Length==1&&textures.Length==1,"shared instance references");rows.Add(new LoadRow{count=n,visible=renderers.Count(x=>GeometryUtility.TestPlanesAABB(planes,x.bounds)),meshes=1,materials=1,textures=1,meshBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(meshes[0]),cpuMedianMs=times[3]});cam.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);foreach(var o in objs)UnityEngine.Object.DestroyImmediate(o);}return rows.ToArray();}
}
